-- Fix pg_graphql exposures
REVOKE SELECT ON ALL TABLES IN SCHEMA public FROM anon;

-- Fix Security Definer Functions
REVOKE EXECUTE ON FUNCTION public.admin_delete_user_data(uuid, uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.admin_update_profile(uuid, uuid, text, text, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.audit_log_row_change() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.prevent_currency_code_update() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.set_audit_changed_by(uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.has_permission(uuid, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.is_admin(uuid) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION public.admin_delete_user_data(uuid, uuid) TO service_role;
GRANT EXECUTE ON FUNCTION public.admin_update_profile(uuid, uuid, text, text, boolean) TO service_role;
GRANT EXECUTE ON FUNCTION public.has_permission(uuid, text) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.is_admin(uuid) TO authenticated, service_role;

-- Fix missing search_path
ALTER FUNCTION public.audit_log_diff(jsonb, jsonb) SET search_path = '';
ALTER FUNCTION public.prevent_currency_code_update() SET search_path = '';
ALTER FUNCTION public.set_audit_changed_by(uuid) SET search_path = '';

