-- Fix RLS Policies by wrapping auth.uid() in (select auth.uid())
ALTER POLICY "self update profile" ON public.profiles TO authenticated USING ((id = (select auth.uid()))) ;
ALTER POLICY "admins manage profiles" ON public.profiles TO authenticated USING (has_permission((select auth.uid()), 'users.manage'::text)) WITH CHECK (has_permission((select auth.uid()), 'users.manage'::text)) ;
ALTER POLICY "manage pgroups" ON public.permission_groups TO authenticated USING (has_permission((select auth.uid()), 'permissions.manage'::text)) WITH CHECK (has_permission((select auth.uid()), 'permissions.manage'::text)) ;
